function KeyGen(g):
    x <- random scalar in [1, order(g))
    X <- x . g            # scalar multiplication in G
    return (sk=x, pk=X)

function Sign(sk=x, message m):
    H <- HashToGroup(m)   # message hashed to an element of G
    sigma <- x . H
    return sigma

function Verify(pk=X, message m, sigma, g):
    H <- HashToGroup(m)
    return e(sigma, g) == e(H, X)   # one equality of two pairings

